import yaml, json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})

# Find all K-curve related experiments with success/ANALYZING status
k_curve = {}
for eid, exp in exps.items():
    if 'perlayer_kl_k' in eid and exp.get('status') in ('DONE', 'ANALYZING'):
        conclusion = exp.get('conclusion', '')
        metrics = exp.get('metrics', {})
        if conclusion == 'success' or exp.get('status') == 'ANALYZING':
            k_curve[eid] = {
                'status': exp['status'],
                'conclusion': conclusion,
                'metrics': metrics,
                'hypothesis': exp.get('hypothesis', '')[:100]
            }

# Also get K=1 baseline (perlayer_kl per-layer results)
for eid, exp in exps.items():
    if eid.startswith('perlayer_kl_') and 'k' not in eid.split('perlayer_kl_')[1][:2] and exp.get('conclusion') == 'success':
        k_curve[eid] = {
            'status': exp['status'],
            'conclusion': exp.get('conclusion', ''),
            'metrics': exp.get('metrics', {}),
            'hypothesis': exp.get('hypothesis', '')[:100]
        }

print(json.dumps(k_curve, indent=2, default=str))
" 2>&1 | head -120

